{
  "name": "precog-skill",
  "version": "1.0.0",
  "type": "module",
  "description": "OpenClaw skill for PrecogMasterV8 prediction markets",
  "scripts": {
    "test":        "vitest run",
    "test:markets": "vitest run tests/markets.test.mjs",
    "test:trade":   "vitest run tests/trade.test.mjs"
  },
  "dependencies": {
    "viem": "^2.0.0"
  },
  "devDependencies": {
    "vitest": "^1.0.0"
  },
  "openclaw": {
    "envVars": {
      "PRIVATE_KEY": "required — secp256k1 private key (0x-prefixed) for signing transactions. Written to ~/.openclaw/.env by setup.mjs --generate. Never transmitted over the network.",
      "PRECOG_RPC_URL": "optional — override the default public RPC endpoints. Use a trusted endpoint only.",
      "PRECOG_NETWORK": "optional — default network: 'sepolia' (testnet, default) or 'mainnet' (Base mainnet, real funds). Can be overridden per-command with --network."
    },
    "configPaths": {
      "~/.openclaw/.env": "created by setup.mjs --generate. Stores PRIVATE_KEY in plaintext. Treat as a wallet key file: restrict permissions and back it up."
    },
    "networks": {
      "sepolia": { "chainId": 84532, "contract": "0x61ec71F1Fd37ecc20d695E83F3D68e82bEfe8443" },
      "mainnet": { "chainId": 8453,  "contract": "0x00000000000c109080dfa976923384b97165a57a" }
    }
  }
}

#!/usr/bin/env node
// Buy outcome shares in a Precog prediction market.
// Always run quote.mjs first to confirm cost with the user.
//
// Usage:
//   node buy.mjs --market <id> --outcome <n> --shares <amount> --max <usdc>
//
// --max is the maximum USDC to spend (e.g. 40 for $40). Slippage defaults to 1%.
// Env: PRIVATE_KEY (required), PRECOG_RPC_URL (optional)
import { fileURLToPath } from "url";
import * as client from "./lib/client.mjs";
import { parseArgs, requireArgs } from "./lib/args.mjs";

export async function main(deps = {}) {
  const _parseArgs   = deps.parseArgs   ?? parseArgs;
  const _requireArgs = deps.requireArgs ?? requireArgs;
  // ── Args ──────────────────────────────────────────────────────────────────
  const a = _parseArgs();
  if (a.network) client.setNetwork(a.network);

  const { multiread, write, getWallet, ensureApproval, outcomes, toFP64, toRaw, MASTER_ADDRESS } =
    { ...client, ...deps };
  _requireArgs(a, ["market", "outcome", "shares", "max"]);

  const marketId = BigInt(a.market);
  const outcome  = parseInt(a.outcome);
  const sharesFP = toFP64(a.shares);
  const slippage = parseFloat(a.slippage ?? "1");

  // ── Account & collateral ──────────────────────────────────────────────────
  const { account, wallet } = getWallet();

  const [colRes, marketRes] = await multiread([
    ["marketCollateralInfo", [marketId]],
    ["markets",              [marketId]],
  ]);
  const [colToken, , colSymbol, colDecimals] = colRes;
  const market = marketRes;
  const dec    = Number(colDecimals);
  const maxRaw = toRaw((parseFloat(a.max) * (1 + slippage / 100)).toFixed(dec), dec);

  // ── Market info & guard ───────────────────────────────────────────────────
  const [question, , , , outcomesRaw, , , , , endTs] = market;

  if (Date.now() / 1000 > Number(endTs)) {
    console.error("Market has ended.");
    process.exit(1);
  }

  const outs  = outcomes(outcomesRaw);
  const label = outs[outcome - 1] ?? `Outcome ${outcome}`;

  console.log(`\nBuying ${a.shares} shares of [${label}] on market ${a.market}`);
  console.log(`Max spend: ${a.max} ${colSymbol} (+${slippage}% slippage)`);
  console.log(`Wallet: ${account.address}\n`);

  // ── Approve token spend and execute buy ───────────────────────────────────
  await ensureApproval(wallet, account, colToken, MASTER_ADDRESS, maxRaw);
  await write(wallet, account, "marketBuy", [marketId, BigInt(outcome), sharesFP, maxRaw]);

  console.log(`\n✓ Bought ${a.shares} shares of ${label} on market ${a.market}`);
  return { label, shares: a.shares, market: a.market };
}

if (process.argv[1] === fileURLToPath(import.meta.url)) {
  main().catch(e => { console.error(e.message); process.exit(1); });
}

// CLI argument utilities shared by all scripts.
//
// parseArgs   — minimal --key value / --key=value / --flag parser
// requireArgs — exits with an error listing any missing required flags
// getChainFromArgs — reads --chain or CHAIN env (currently unused by scripts)

// Minimal CLI arg parser. Supports --key value and --key=value.
export function parseArgs(argv = process.argv.slice(2)) {
  const args = {};
  for (let i = 0; i < argv.length; i++) {
    const arg = argv[i];
    if (!arg.startsWith("--")) continue;
    const eqIdx = arg.indexOf("=");
    if (eqIdx !== -1) {
      args[arg.slice(2, eqIdx)] = arg.slice(eqIdx + 1);
    } else {
      const next = argv[i + 1];
      if (next === undefined || next.startsWith("--")) {
        args[arg.slice(2)] = true;
      } else {
        args[arg.slice(2)] = argv[++i];
      }
    }
  }
  return args;
}

export function requireArgs(args, required) {
  const missing = required.filter(k => !(k in args));
  if (missing.length) {
    console.error(`Missing required args: ${missing.map(k => `--${k}`).join(", ")}`);
    process.exit(1);
  }
}

export function getChainFromArgs(args) {
  return args.chain || process.env.CHAIN || null;
}

import { createPublicClient, createWalletClient, http, fallback } from "viem";
import { baseSepolia, base } from "viem/chains";
import { privateKeyToAccount } from "viem/accounts";
import { readFileSync, existsSync } from "fs";
import { homedir } from "os";
import { join, dirname } from "path";
import { fileURLToPath } from "url";

// ── Load ~/.openclaw/.env ─────────────────────────────────────────────────────

const ENV_FILE = join(homedir(), ".openclaw", ".env");
if (existsSync(ENV_FILE)) {
  for (const line of readFileSync(ENV_FILE, "utf8").split("\n")) {
    const m = line.match(/^([A-Z_][A-Z0-9_]*)=(.+)$/);
    if (m && !process.env[m[1]]) process.env[m[1]] = m[2].trim();
  }
}

// ── Network config ────────────────────────────────────────────────────────────

const NETWORKS = {
  sepolia: {
    chain:   baseSepolia,
    address: "0x61ec71F1Fd37ecc20d695E83F3D68e82bEfe8443",
    rpcs: [
      "https://sepolia.base.org",
      "https://base-sepolia-rpc.publicnode.com"
    ],
  },
  mainnet: {
    chain:   base,
    address: "0x00000000000c109080dfa976923384b97165a57a",
    rpcs: [
      "https://mainnet.base.org",
      "https://base-rpc.publicnode.com"
    ],
  },
};

function _buildTransport(cfg) {
  return process.env.PRECOG_RPC_URL
    ? http(process.env.PRECOG_RPC_URL)
    : fallback(cfg.rpcs.map(url => http(url)));
}

let _networkKey = (process.env.PRECOG_NETWORK || "sepolia").toLowerCase();
if (!NETWORKS[_networkKey]) _networkKey = "sepolia";

let _cfg       = NETWORKS[_networkKey];
let chain      = _cfg.chain;
let transport  = _buildTransport(_cfg);

export let MASTER_ADDRESS = _cfg.address;
export let pub            = createPublicClient({ chain, transport });

/** Switch to a different network. Call this before any contract reads/writes. */
export function setNetwork(network) {
  const key = network.toLowerCase();
  if (!NETWORKS[key]) throw new Error(`Unknown network: "${network}". Use "sepolia" or "mainnet".`);
  _networkKey   = key;
  _cfg          = NETWORKS[key];
  chain         = _cfg.chain;
  transport     = _buildTransport(_cfg);
  MASTER_ADDRESS = _cfg.address;
  pub            = createPublicClient({ chain, transport });
}

// ── ABI ───────────────────────────────────────────────────────────────────────

const __dir  = dirname(fileURLToPath(import.meta.url));
const ABI_PATH = join(__dir, "../../abi/PrecogMasterV8.json");
export const ABI = JSON.parse(readFileSync(ABI_PATH, "utf8"));

// ── Clients ───────────────────────────────────────────────────────────────────

export function getWallet() {
  const pk = process.env.PRIVATE_KEY;
  if (!pk) {
    throw new Error(
      "No wallet found.\nRun: node setup.mjs --generate\n" +
      "Or add PRIVATE_KEY=0x... to ~/.openclaw/.env"
    );
  }
  const account = privateKeyToAccount(pk.startsWith("0x") ? pk : `0x${pk}`);
  const wallet  = createWalletClient({ account, chain, transport });
  return { account, wallet };
}

// ── Contract helpers ──────────────────────────────────────────────────────────

export function read(fn, args = []) {
  return pub.readContract({ address: MASTER_ADDRESS, abi: ABI, functionName: fn, args });
}

export function multiread(calls, { allowFailure = false } = {}) {
  return pub.multicall({
    contracts: calls.map(([functionName, args = []]) => ({
      address: MASTER_ADDRESS,
      abi: ABI,
      functionName,
      args,
    })),
    allowFailure,
  });
}

export async function write(wallet, account, fn, fnArgs) {
  const hash = await wallet.writeContract({
    address: MASTER_ADDRESS, abi: ABI, functionName: fn, args: fnArgs, account,
  });
  process.stdout.write(`Tx sent: ${hash}\nWaiting for confirmation...`);
  const receipt = await pub.waitForTransactionReceipt({ hash });
  console.log(` confirmed (block ${receipt.blockNumber})`);
  return receipt;
}

// ── ERC20 helpers ─────────────────────────────────────────────────────────────

const ERC20_ABI = [
  { name: "balanceOf", type: "function", stateMutability: "view",
    inputs: [{ type: "address" }], outputs: [{ type: "uint256" }] },
  { name: "allowance", type: "function", stateMutability: "view",
    inputs: [{ type: "address" }, { type: "address" }], outputs: [{ type: "uint256" }] },
  { name: "approve",   type: "function", stateMutability: "nonpayable",
    inputs: [{ type: "address" }, { type: "uint256" }], outputs: [{ type: "bool" }] },
];

export async function tokenBalance(token, addr) {
  return pub.readContract({ address: token, abi: ERC20_ABI, functionName: "balanceOf", args: [addr] });
}

export async function ensureApproval(wallet, account, token, spender, amount) {
  const allowance = await pub.readContract({
    address: token, abi: ERC20_ABI, functionName: "allowance",
    args: [account.address, spender],
  });
  if (allowance >= amount) return;
  console.log(`Approving ${token}...`);
  const hash = await wallet.writeContract({
    address: token, abi: ERC20_ABI, functionName: "approve",
    args: [spender, amount], account,
  });
  await pub.waitForTransactionReceipt({ hash });
  console.log("Approved.");
}

// ── Formatting ────────────────────────────────────────────────────────────────

export const TWO_POW_64 = 2n ** 64n;

export function toFP64(shares) {
  const [i, d = ""] = String(shares).split(".");
  const dec18 = BigInt(i) * 10n ** 18n + BigInt(d.padEnd(18, "0").slice(0, 18));
  return (dec18 * TWO_POW_64) / 10n ** 18n;
}

export function fromFP64(fp) {
  return Number((BigInt(fp) * 10000n) / TWO_POW_64) / 10000;
}

export function toRaw(amount, decimals) {
  const [i, d = ""] = String(amount).split(".");
  return BigInt(i) * 10n ** BigInt(decimals) + BigInt(d.padEnd(decimals, "0").slice(0, decimals));
}

export function fromRaw(raw, decimals) {
  const d     = 10n ** BigInt(decimals);
  const whole = raw / d;
  const frac  = raw % d;
  return `${whole}.${String(frac).padStart(decimals, "0").slice(0, 4)}`;
}

export function pct(price1e18) {
  return (Number(price1e18) / 1e18 * 100).toFixed(1);
}

export function outcomes(raw) {
  return raw.split("|").map(s => s.trim()).filter(Boolean);
}

export function status(endTs) {
  return Date.now() / 1000 < Number(endTs) ? "active" : "ended";
}

export function date(ts) {
  return new Date(Number(ts) * 1000).toLocaleDateString("en-US",
    { month: "short", day: "numeric", year: "numeric" });
}

// LS-LMSR pricing model and market math helpers used by quote.mjs.
//
// LSLMSR  — full class implementation of the Logarithmic Scoring Rule
//           Market Maker with liquidity-sensitive parameter (alpha).
//           Used for --price target resolution (maxSharesFromPrice).
//
// marketSharesFromCost / marketPriceAfterTrade / getFuturePriceAfterTrade —
//           standalone functions that mirror the on-chain cost curve.
//           Used for --cost / --all resolution and probability-after-trade display.

// ── LSLMSR class ──────────────────────────────────────────────────────────────

export class LSLMSR {
    constructor(outcomes, alpha, initialShares = 0, sellFee = 0) {
      this.outcomes = outcomes;
      this.alpha = alpha;
      this.initialShares = initialShares;
      this.sellFee = sellFee;
  
      this.q = {};
      for (const o of outcomes) this.q[o] = this.initialShares;
  
      this.initialCost = this.cost();
      this.collectedFees = 0;
    }
  
    static fromState(outcomesBalances, alpha) {
      const outcomes = Object.keys(outcomesBalances);
      const initialShares = Math.min(...Object.values(outcomesBalances));
      const market = new LSLMSR(outcomes, alpha, initialShares);
      market.q = outcomesBalances;
      return market;
    }
  
    b(q = this.q) {
      return this.alpha * this.outcomes.reduce((sum, o) => sum + q[o], 0);
    }
  
    cost(q = this.q) {
      const bq = this.b(q);
      if (bq === 0) return 0;
  
      const sumExp = this.outcomes.reduce((sum, o) => sum + Math.exp(q[o] / bq), 0);
      return bq * Math.log(sumExp);
    }
  
    prices() {
      const result = {};
      for (const o of this.outcomes) {
        result[o] = this.tradeCost(o, 1);
      }
      return result;
    }
  
    trade(outcome, deltaQ) {
      const oldCost = this.cost();
      this.q[outcome] += deltaQ;
      const newCost = this.cost();
      return Math.abs(newCost - oldCost);
    }
  
    buy(outcome, shares) {
      return this.trade(outcome, Math.abs(shares));
    }
  
    sell(outcome, shares) {
      const tradeReturn = this.trade(outcome, -Math.abs(shares));
      const tradeFee = tradeReturn * this.sellFee;
      this.collectedFees += tradeFee;
      return tradeReturn - tradeFee;
    }
  
    tradeCost(outcome, deltaQ) {
      const tempQ = { ...this.q };
      tempQ[outcome] += deltaQ;
  
      const tradeCost = Math.abs(this.cost(tempQ) - this.cost(this.q));
      let tradeFee = 0;
  
      if (deltaQ < 0) tradeFee = tradeCost * this.sellFee;
  
      return tradeCost - tradeFee;
    }
  
    getBalances() {
      return { ...this.q };
    }
  
    getOutcome(outcome_index) {
      return this.outcomes[outcome_index - 1];
    }
  
    pricesAfterTrade(outcome, deltaQ) {
      const tempQ = { ...this.q };
      tempQ[outcome] += deltaQ;
  
      const result = {};
  
      for (const o of this.outcomes) {
        const qWith1More = { ...tempQ };
        qWith1More[o] += 1;
        result[o] = this.cost(qWith1More) - this.cost(tempQ);
      }
  
      return result;
    }
  
    maxSharesFromCost(outcome, budget, precision = 1e-9) {
      let low = 0;
      let high = 1;
  
      while (this.tradeCost(outcome, high) < budget) {
        high *= 2;
      }
  
      while (high - low > precision) {
        const mid = (low + high) / 2;
        const cost = this.tradeCost(outcome, mid);
  
        if (cost > budget) {
          high = mid;
        } else {
          low = mid;
        }
      }
  
      return low;
    }
  
    maxSharesFromPrice(outcome, targetPrice, precision = 1e-9) {
      let low = 0;
      let high = 1;
  
      while (true) {
        const price = this.pricesAfterTrade(outcome, high)[outcome];
        if (price >= targetPrice) break;
        high *= 2;
      }
  
      while (high - low > precision) {
        const mid = (low + high) / 2;
        const price = this.pricesAfterTrade(outcome, mid)[outcome];
  
        if (price > targetPrice) {
          high = mid;
        } else {
          low = mid;
        }
      }
  
      return low;
    }
  
    maxLoss() {
      const n = this.outcomes.length;
      const overround = this.alpha * (n * Math.log(n));
      return this.initialShares * overround;
    }
  
    addLiquidity(value) {
      const k = value / this.cost();
  
      for (const outcome in this.outcomes) {
        this.buy(outcome, this.q[outcome] * k);
      }
    }
  }



// ── Standalone market cost / price functions ──────────────────────────────────

/**
 * Calculate the total amount of collateral deposited in a Market
 *
 * @param shares - List of shares balances for all outcomes in the Market
 * @param alpha - Fixed PrecogMarket contract variable defined on market initialization
 */
const marketCost = (shares, alpha) => {
    const totalShares = shares.reduce((sum, s) => sum + s, 0);
    const beta = totalShares * alpha;
  
    const sumTotal = shares.reduce((sum, s) => (s === 0 ? sum : sum + Math.exp(s / beta)), 0);
    return beta * Math.log(sumTotal);
  };
  
  /**
   * Calculate the total amount of collateral that will be deposited after a trade
   */
  const marketCostAfterTrade = (shares, alpha, outcome, amount) => {
    const newShares = [...shares];
    newShares[outcome] += amount;
  
    return marketCost(newShares, alpha);
  };
  
  /**
   * Calculate the amount of collateral required for a trade
   */
  const marketTradeCost = (shares, alpha, outcome, amount) => {
    const cost = marketCost(shares, alpha);
    const costAfterTrade = marketCostAfterTrade(shares, alpha, outcome, amount);
    return Math.abs(costAfterTrade - cost);
  };
  
  /**
   * Calculate shares purchasable from a given cost
   */
  export const marketSharesFromCost = (shares, alpha, outcome, totalCost) => {
    const maxIterations = 100;
    const tolerance = 0.0001;
  
    let low = totalCost * 0.999;
    let high = totalCost * 10000;
    let mid = 0;
  
    for (let i = 0; i < maxIterations; i++) {
      mid = (low + high) / 2;
      const cost = marketTradeCost(shares, alpha, outcome, mid);
  
      if (Math.abs(cost - totalCost) < tolerance) return mid;
      if (cost < totalCost) low = mid;
      else high = mid;
    }
  
    return mid;
  };
  
  /**
   * Calculate price of a single share after a trade
   */
  export const marketPriceAfterTrade = (shares, alpha, outcome, amount) => {
    const costAfterTrade = marketCostAfterTrade(shares, alpha, outcome, amount);
  
    const oneShareDelta = amount > 0 ? amount + 1 : amount - 1;
    const costAfterTradeWithDelta = marketCostAfterTrade(shares, alpha, outcome, oneShareDelta);
  
    return Math.abs(costAfterTradeWithDelta - costAfterTrade);
  };
  
  /**
   * Calculates the price of buying/selling one share after a trade is completed
   */
  export const getFuturePriceAfterTrade = (
    shares,
    alpha,
    outcome,
    tradeAmount
  ) => {
    const sharesAfterTrade = [...shares];
    sharesAfterTrade[outcome] += tradeAmount;
  
    return marketTradeCost(sharesAfterTrade, alpha, outcome, 1);
  };

#!/usr/bin/env node
// Show detailed info for a single market.
//
// Usage:
//   node market.mjs --market <id>            # title, category, all outcomes + probabilities
//   node market.mjs --market <id> --criteria # also shows resolution criteria
//
// Env: PRECOG_RPC_URL (optional)
import { fileURLToPath } from "url";
import * as client from "./lib/client.mjs";
import { parseArgs, requireArgs } from "./lib/args.mjs";

export async function main(deps = {}) {
  const _parseArgs = deps.parseArgs ?? parseArgs;
  const a = _parseArgs();
  if (a.network) client.setNetwork(a.network);

  const { multiread, outcomes, pct, status, date } = { ...client, ...deps };
  requireArgs(a, ["market"]);

  const id = Number(a.market);
  const [marketRes, pricesRes, colRes] = await multiread([
    ["markets",              [BigInt(id)]],
    ["marketPrices",         [BigInt(id)]],
    ["marketCollateralInfo", [BigInt(id)]],
  ], { allowFailure: true });

  const market = marketRes.result;
  const [question, resolutionCriteria, , category, outcomesRaw, , , , , endTs] = market;
  const buyPrices = pricesRes.status === "success" ? pricesRes.result[0] : null;
  const token     = colRes.status === "success"    ? colRes.result[2]    : null;

  const rawOuts = outcomes(outcomesRaw);
  const outs = (rawOuts.length === 1 && rawOuts[0].includes(","))
    ? rawOuts[0].split(",").map(s => s.trim()).filter(Boolean)
    : rawOuts;

  const s = status(endTs);

  // ── Header ────────────────────────────────────────────────────────────────
  const catPart = category ? `  ·  ${category}` : "";
  console.log(`\n📊  Market ${id}${catPart}`);
  console.log(`${question}`);

  const tokPart  = token ? `  💰 ${token}` : "";
  const statIcon = s === "active" ? "🟢" : "🔴";
  console.log(`${statIcon} ${s.charAt(0).toUpperCase() + s.slice(1)}  📅 ${date(endTs)}${tokPart}\n`);

  // ── Outcomes ──────────────────────────────────────────────────────────────
  const medals = ["🥇", "🥈", "🥉"];

  // Rank by price descending (if prices available)
  const ranked = outs.map((label, idx) => {
    const price = buyPrices ? Number(buyPrices[idx + 1]) / 1e18 : null;
    return { n: idx + 1, label, price };
  });
  if (buyPrices) ranked.sort((a, b) => b.price - a.price);

  const maxLabel = Math.max(...ranked.map(r => r.label.length));

  for (let i = 0; i < ranked.length; i++) {
    const { n, label, price } = ranked[i];
    const icon   = medals[i] ?? "   ";
    const padded = label.padEnd(maxLabel);
    const pctStr = price !== null ? `  ${(price * 100).toFixed(1)}%` : "";
    console.log(`${icon}  [${n}] ${padded}${pctStr}`);
  }

  // ── Resolution criteria ───────────────────────────────────────────────────
  if ("criteria" in a) {
    if (resolutionCriteria) {
      console.log(`\n📝  Resolution Criteria\n${resolutionCriteria}`);
    } else {
      console.log("\n📝  No resolution criteria on record.");
    }
  }

  console.log("");
  return { id, question, category, resolutionCriteria, outs, status: s };
}

if (process.argv[1] === fileURLToPath(import.meta.url)) {
  main().catch(e => { console.error(e.message); process.exit(1); });
}

#!/usr/bin/env node
// List Precog prediction markets.
//
// Usage:
//   node markets.mjs           # active markets only, with predictions
//   node markets.mjs --all     # all markets (titles only, no prices)
//
// Env: PRECOG_RPC_URL (optional)
import { fileURLToPath } from "url";
import * as client from "./lib/client.mjs";
import { parseArgs } from "./lib/args.mjs";

export async function main(deps = {}) {
  const _parseArgs = deps.parseArgs ?? parseArgs;
  const a = _parseArgs();
  if (a.network) client.setNetwork(a.network);

  const { read, multiread, outcomes, pct, status, date } = { ...client, ...deps };
  const total = await read("createdMarkets");
  if (total === 0n) { console.log("No markets found."); return []; }

  const showAll = "all" in a;
  const result  = [];

  // Batch fetch all markets in one call
  const marketResults = await multiread(
    Array.from({ length: Number(total) }, (_, i) => ["markets", [BigInt(i)]])
  );

  // ── --all: list every market with status, no prices ───────────────────────
  if (showAll) {
    console.log(`\nAll Markets (${total})\n`);
    for (let i = 0; i < marketResults.length; i++) {
      const [question, , , , , , , , , endTs] = marketResults[i];
      const s = status(endTs);
      console.log(`  [${i}]  ${question}  [${s}]`);
      result.push({ id: i, question, status: s });
    }
  } else {
    // ── Default: active markets with leading prediction and token ─────────────
    const activeIds = [];
    for (let i = 0; i < marketResults.length; i++) {
      if (status(marketResults[i][9]) === "active") activeIds.push(i);
    }

    if (activeIds.length === 0) {
      console.log("\nNo active markets.\n");
      return result;
    }

    // Batch fetch prices + collateral for all active markets in one call
    const priceAndColResults = await multiread([
      ...activeIds.map(i => ["marketPrices",         [BigInt(i)]]),
      ...activeIds.map(i => ["marketCollateralInfo",  [BigInt(i)]]),
    ], { allowFailure: true });

    const pricesArr = priceAndColResults.slice(0, activeIds.length);
    const colArr    = priceAndColResults.slice(activeIds.length);

    const active = [];
    for (let j = 0; j < activeIds.length; j++) {
      const id     = activeIds[j];
      const market = marketResults[id];
      const [question, , , , outcomesRaw, , , , , endTs] = market;

      const rawOuts = outcomes(outcomesRaw);
      const outs = (rawOuts.length === 1 && rawOuts[0].includes(","))
        ? rawOuts[0].split(",").map(s => s.trim()).filter(Boolean)
        : rawOuts;

      let prediction = null;
      const prRes = pricesArr[j];
      if (prRes.status === "success") {
        const buyPrices = prRes.result[0];
        let bestIdx = 1;
        for (let k = 2; k <= outs.length; k++) {
          if (buyPrices[k] > buyPrices[bestIdx]) bestIdx = k;
        }
        prediction = { label: outs[bestIdx - 1], pct: pct(buyPrices[bestIdx]) };
      }

      let token = null;
      const coRes = colArr[j];
      if (coRes.status === "success") {
        token = coRes.result[2];
      }

      active.push({ id, question, endTs, outs, prediction, token });
    }

    console.log(`\nActive Markets (${active.length})\n`);
    for (const m of active) {
      const tok = m.token ? `  💰 ${m.token}` : "";
      console.log(`[${m.id}] ${m.question}`);
      if (m.prediction) {
        console.log(`    📈 ${m.prediction.label}  ${m.prediction.pct}%${tok}  📅 ${date(m.endTs)}`);
      } else {
        console.log(`    📅 ${date(m.endTs)}`);
      }
      console.log("");
      result.push(m);
    }
  }

  if (showAll) console.log("");
  return result;
}

if (process.argv[1] === fileURLToPath(import.meta.url)) {
  main().catch(e => { console.error(e.message); process.exit(1); });
}

