// Show share positions for a wallet in a Precog prediction market.
//
// Usage:
//   node positions.mjs --market <id>
//
// Env: PRIVATE_KEY (required), PRECOG_RPC_URL (optional)
import { fileURLToPath } from "url";
import * as client from "./lib/client.mjs";
import { parseArgs, requireArgs } from "./lib/args.mjs";

export async function main(deps = {}) {
  const _parseArgs   = deps.parseArgs   ?? parseArgs;
  const _requireArgs = deps.requireArgs ?? requireArgs;
  const a = _parseArgs();
  if (a.network) client.setNetwork(a.network);

  const { multiread, getWallet, outcomes, fromRaw, pct } = { ...client, ...deps };
  _requireArgs(a, ["market"]);

  const marketId = BigInt(a.market);
  const { account } = getWallet();

  const [marketRes, colRes, accountRes, pricesRes] = await multiread([
    ["markets",              [marketId]],
    ["marketCollateralInfo", [marketId]],
    ["marketAccountInfo",    [marketId, account.address]],
    ["marketPrices",         [marketId]],
  ], { allowFailure: true });

  if (marketRes.status  === "failure") throw new Error("Failed to load market");
  if (colRes.status     === "failure") throw new Error("Failed to load collateral info");
  if (accountRes.status === "failure") throw new Error("Failed to load account info");

  const [question, , , , outcomesRaw]                         = marketRes.result;
  const [, , colSymbol, colDecimals]                          = colRes.result;
  const [totalBuys, totalSells, deposited, withdrawn, redeemed, balances] = accountRes.result;
  const buyPrices = pricesRes.status === "success" ? pricesRes.result[0] : null;

  const dec  = Number(colDecimals);
  const outs = outcomes(outcomesRaw);

  const netCost = deposited - withdrawn - redeemed;

  // ── Header ────────────────────────────────────────────────────────────────
  console.log(`\n💼  Market ${a.market}`);
  console.log(`${question}\n`);
  console.log(`👛  ${account.address}`);
  console.log(`💵  Net cost  ${fromRaw(netCost < 0n ? 0n : netCost, dec)} ${colSymbol}  ·  📥 ${totalBuys} buys  📤 ${totalSells} sells\n`);

  // ── Shares ────────────────────────────────────────────────────────────────
  const medals = ["🥇", "🥈", "🥉"];
  const held = [];

  for (let i = 1; i < balances.length; i++) {
    if (balances[i] === 0n) continue;
    const label       = outs[i - 1] ?? `Outcome ${i}`;
    const sharesHuman = parseFloat((Number(balances[i]) / 1e18).toFixed(4));
    const priceStr    = buyPrices ? `  ·  ${pct(buyPrices[i])}%` : "";
    held.push({ outcome: i, label, shares: sharesHuman, priceStr });
  }

  if (held.length === 0) {
    console.log("🎯  No shares held in this market.\n");
  } else {
    console.log("🎯  Shares held");
    const maxLabel = Math.max(...held.map(h => h.label.length));
    held.forEach((h, idx) => {
      const icon   = medals[idx] ?? "   ";
      const padded = h.label.padEnd(maxLabel);
      console.log(`${icon}  [${h.outcome}] ${padded}   ${h.shares} shares${h.priceStr}`);
    });
    console.log("");
  }

  return { netCost, totalBuys, totalSells, held };
}

if (process.argv[1] === fileURLToPath(import.meta.url)) {
  main().catch(e => { console.error(e.message); process.exit(1); });
}

#!/usr/bin/env node
// Quote the cost to buy or sell outcome shares in a Precog market.
// Always run before buy or sell — show the output to the user and confirm.
//
// Usage:
//   node quote.mjs --market <id> --outcome <n> --shares <amount> [--buy | --sell]
//   node quote.mjs --market <id> --outcome <n> --cost <usdc>     [--buy | --sell]
//   node quote.mjs --market <id> --outcome <n> --price <0.0-1.0> [--buy | --sell]
//
// IMPORTANT — choosing the right flag:
//   User says "buy N shares"                      → --shares N
//   User says "spend $X" / "for $X" / "budget $X" → --cost X
//   User says "reach X%" / "move to X%" /
//             "push to X%" / "target X%"           → --price 0.X   ← DO NOT guess shares manually
//   User says "use all my balance" / "all in"      → --all         ← reads wallet balance automatically
//
// --outcome is 1-based (1 = first outcome, usually YES).
// --buy / --sell show only that side. Omit both to show buy and sell.
// Env: PRECOG_RPC_URL (optional)
import { fileURLToPath } from "url";
import * as client from "./lib/client.mjs";
import { parseArgs, requireArgs } from "./lib/args.mjs";
import { LSLMSR, marketSharesFromCost, marketPriceAfterTrade, getFuturePriceAfterTrade } from "./lib/helper.mjs";

export async function main(deps = {}) {
  const _parseArgs   = deps.parseArgs   ?? parseArgs;
  const _requireArgs = deps.requireArgs ?? requireArgs;
  // ── Args ──────────────────────────────────────────────────────────────────
  const a = _parseArgs();
  if (a.network) client.setNetwork(a.network);

  const { multiread, outcomes, pct, toFP64, fromFP64, fromRaw, tokenBalance, getWallet } = { ...client, ...deps };
  _requireArgs(a, ["market", "outcome"]);

  if (!("shares" in a) && !("cost" in a) && !("price" in a) && !("all" in a)) {
    throw new Error("Provide one of: --shares <n>, --cost <usdc>, --price <0.0-1.0>, --all");
  }

  const showBuy  = !("sell" in a);
  const showSell = !("buy"  in a);

  const marketId = BigInt(a.market);
  const outcome  = parseInt(a.outcome);

  // ── Batch 1: market info, collateral, setup, shares, prices ──────────────
  const [marketRes, colRes, setupRes, sharesRes, pricesRes] = await multiread([
    ["markets",              [marketId]],
    ["marketCollateralInfo", [marketId]],
    ["marketSetupInfo",      [marketId]],
    ["marketSharesInfo",     [marketId]],
    ["marketPrices",         [marketId]],
  ], { allowFailure: true });

  if (marketRes.status  === "failure") throw new Error("Failed to load market");
  if (colRes.status     === "failure") throw new Error("Failed to load collateral info");
  if (setupRes.status   === "failure") throw new Error("Failed to load market setup info");
  if (sharesRes.status  === "failure") throw new Error("Failed to load market shares info");

  const [question, , , , outcomesRaw]  = marketRes.result;
  const [colToken, , colSymbol, colDecimals] = colRes.result;
  const [, alphaFP, , sellFeeFP]       = setupRes.result;
  const [, sharesBalancesFP]           = sharesRes.result;

  const rawOuts = outcomes(outcomesRaw);
  const outcomeList = (rawOuts.length === 1 && rawOuts[0].includes(","))
    ? rawOuts[0].split(",").map(s => s.trim()).filter(Boolean)
    : rawOuts;
  const label = outcomeList[outcome - 1] ?? `Outcome ${outcome}`;

  const alpha    = fromFP64(alphaFP);
  const sellFee  = fromFP64(sellFeeFP);
  const sharesArr = sharesBalancesFP.map(fp => fromFP64(fp)); // keep 1-indexed

  // ── Resolve share count from flag ─────────────────────────────────────────
  let sharesNum;

  if ("all" in a) {
    const { account } = getWallet();
    const balRaw  = await tokenBalance(colToken, account.address);
    const balance = Number(balRaw) / 10 ** Number(colDecimals);
    console.log(`  💰  Wallet balance : ${balance.toFixed(4)} ${colSymbol}`);
    sharesNum = Math.floor(marketSharesFromCost(sharesArr, alpha, outcome, balance));
  } else if ("cost" in a) {
    sharesNum = Math.floor(marketSharesFromCost(sharesArr, alpha, outcome, parseFloat(a.cost)));
  } else if ("price" in a) {
    const outcomesBalances = {};
    for (let j = 0; j < outcomeList.length; j++) {
      outcomesBalances[outcomeList[j]] = sharesArr[j + 1];
    }
    const lslmsr   = LSLMSR.fromState(outcomesBalances, alpha);
    lslmsr.sellFee = sellFee;
    sharesNum = Math.floor(lslmsr.maxSharesFromPrice(label, parseFloat(a.price)));
  } else {
    sharesNum = parseFloat(a.shares);
  }

  if (sharesNum <= 0) {
    console.log("\n❌  Not enough for even 1 share.\n");
    return null;
  }

  // ── Batch 2: on-chain price quotes ────────────────────────────────────────
  const sharesFP  = toFP64(sharesNum);
  const [buyCostFP, sellRetFP] = await multiread([
    ["marketBuyPrice",  [marketId, BigInt(outcome), sharesFP]],
    ["marketSellPrice", [marketId, BigInt(outcome), sharesFP]],
  ]);
  const buyCost   = fromFP64(BigInt(buyCostFP));
  const sellRet   = fromFP64(BigInt(sellRetFP));
  const perShare  = buyCost / sharesNum;

  // ── Local price simulation (future probability after trade) ───────────────
  const futureBuyPrice  = marketPriceAfterTrade(sharesArr, alpha, outcome, sharesNum);
  const futureSellPrice = getFuturePriceAfterTrade(sharesArr, alpha, outcome, -sharesNum);
  const maxReturn       = sharesNum;
  const buyProfit       = maxReturn - buyCost;
  const sellPerShare    = sellRet / sharesNum;

  let prob = "N/A";
  if (pricesRes.status === "success") {
    prob = pct(pricesRes.result[0][outcome]) + "%";
  }

  // ── Output ────────────────────────────────────────────────────────────────
  const hr = "─".repeat(57);

  console.log(`\n📋  Quote — Market ${a.market}: ${question}`);
  console.log(hr);
  console.log(`  🎯  Outcome      : ${label}`);
  console.log(`  🔢  Shares       : ${sharesNum}`);
  console.log(`  📊  Current prob : ${prob}`);

  if (showBuy) {
    console.log(`\n  🛒  Buy ${sharesNum} shares`);
    console.log(`       💵  Cost           : ~${buyCost.toFixed(4)} ${colSymbol}`);
    console.log(`       📏  Price / share  : ${perShare.toFixed(4)} ${colSymbol}`);
    console.log(`       📈  Prob after buy : ${pct(futureBuyPrice)}%  (market moves up ↑)`);
    console.log(`       🏆  Max return     : ${maxReturn.toFixed(4)} ${colSymbol}   (+${buyProfit.toFixed(4)} profit if "${label}" wins)`);
    console.log(`\n  ⚡  Suggested --max for buy  : ${(buyCost * 1.01).toFixed(4)}`);
  }

  if (showSell) {
    console.log(`\n  💸  Sell ${sharesNum} shares`);
    console.log(`       💵  Return         : ~${sellRet.toFixed(4)} ${colSymbol}`);
    console.log(`       📏  Price / share  : ${sellPerShare.toFixed(4)} ${colSymbol}`);
    console.log(`       📉  Prob after sell: ${pct(futureSellPrice)}%  (market moves down ↓)`);
    console.log(`\n  ⚡  Suggested --min for sell : ${(sellRet * 0.99).toFixed(4)}`);
  }

  console.log(`─── Paste ALL lines above verbatim to the user before asking to confirm ───`);
  console.log("");

  return { label, shares: sharesNum, buyCost, sellRet, perShare, prob,
           futureBuyPrice, futureSellPrice, maxReturn, buyProfit, sellPerShare,
           suggestedMax: buyCost * 1.01, suggestedMin: sellRet * 0.99 };
}

if (process.argv[1] === fileURLToPath(import.meta.url)) {
  main().catch(e => { console.error(e.message); process.exit(1); });
}

#!/usr/bin/env node
// Sell outcome shares in a Precog prediction market.
// Always run quote.mjs first to confirm return with the user.
//
// Usage:
//   node sell.mjs --market <id> --outcome <n> --shares <amount> --min <usdc>
//
// --min is the minimum USDC to accept (e.g. 38 for $38). Slippage defaults to 1%.
// Env: PRIVATE_KEY (required), PRECOG_RPC_URL (optional)
import { fileURLToPath } from "url";
import * as client from "./lib/client.mjs";
import { parseArgs, requireArgs } from "./lib/args.mjs";

export async function main(deps = {}) {
  const _parseArgs   = deps.parseArgs   ?? parseArgs;
  const _requireArgs = deps.requireArgs ?? requireArgs;
  // ── Args ──────────────────────────────────────────────────────────────────
  const a = _parseArgs();
  if (a.network) client.setNetwork(a.network);

  const { multiread, write, getWallet, outcomes, toFP64, toRaw } = { ...client, ...deps };
  _requireArgs(a, ["market", "outcome", "shares", "min"]);

  const marketId = BigInt(a.market);
  const outcome  = parseInt(a.outcome);
  const sharesFP = toFP64(a.shares);
  const slippage = parseFloat(a.slippage ?? "1");

  // ── Account & collateral ──────────────────────────────────────────────────
  const { account, wallet } = getWallet();

  const [colRes, marketRes] = await multiread([
    ["marketCollateralInfo", [marketId]],
    ["markets",              [marketId]],
  ]);
  const [, , colSymbol, colDecimals] = colRes;
  const dec    = Number(colDecimals);
  const minRaw = toRaw((parseFloat(a.min) * (1 - slippage / 100)).toFixed(dec), dec);

  // ── Market outcome label ──────────────────────────────────────────────────
  const [, , , , outcomesRaw] = marketRes;
  const outs  = outcomes(outcomesRaw);
  const label = outs[outcome - 1] ?? `Outcome ${outcome}`;

  console.log(`\nSelling ${a.shares} shares of [${label}] on market ${a.market}`);
  console.log(`Min receive: ${a.min} ${colSymbol} (-${slippage}% slippage)`);
  console.log(`Wallet: ${account.address}\n`);

  // ── Execute sell ──────────────────────────────────────────────────────────
  await write(wallet, account, "marketSell", [marketId, BigInt(outcome), sharesFP, minRaw]);

  console.log(`\n✓ Sold ${a.shares} shares of ${label} on market ${a.market}`);
  return { label, shares: a.shares, market: a.market };
}

if (process.argv[1] === fileURLToPath(import.meta.url)) {
  main().catch(e => { console.error(e.message); process.exit(1); });
}

#!/usr/bin/env node
// Wallet setup for Precog prediction market scripts.
//
// Usage:
//   node setup.mjs              # check wallet status, show address + balances
//   node setup.mjs --generate   # generate a new wallet, save to ~/.openclaw/.env
//
// Env: PRECOG_RPC_URL (optional)
import { existsSync, readFileSync, appendFileSync, mkdirSync } from "fs";
import { homedir } from "os";
import { join } from "path";
import { fileURLToPath } from "url";
import { generatePrivateKey, privateKeyToAccount } from "viem/accounts";
import { formatEther } from "viem";
import * as client from "./lib/client.mjs";
import { parseArgs } from "./lib/args.mjs";

const ENV_DIR  = join(homedir(), ".openclaw");
const ENV_FILE = join(ENV_DIR, ".env");

export async function main(deps = {}) {
  const _parseArgs = deps.parseArgs ?? parseArgs;
  const a0 = _parseArgs();
  if (a0.network) client.setNetwork(a0.network);

  const { pub, read, tokenBalance, fromRaw } = { ...client, ...deps };
  const {
    existsSync:     _existsSync     = existsSync,
    readFileSync:   _readFileSync   = readFileSync,
    appendFileSync: _appendFileSync = appendFileSync,
    mkdirSync:      _mkdirSync      = mkdirSync,
    envFile:        _envFile        = ENV_FILE,
    envDir:         _envDir         = ENV_DIR,
    getPrivateKey:  _getPrivateKey  = () => process.env.PRIVATE_KEY,
  } = deps;

  const a = a0;

  // ── Generate ────────────────────────────────────────────────────────────────
  if ("generate" in a) {
    const existingKey = _getPrivateKey();
    if (existingKey) {
      console.error(`Wallet already set: ${privateKeyToAccount(existingKey).address}`);
      console.error("Remove PRIVATE_KEY from ~/.openclaw/.env first.");
      return { error: "already_exists" };
    }
    if (_existsSync(_envFile) && _readFileSync(_envFile, "utf8").includes("PRIVATE_KEY=")) {
      console.error("PRIVATE_KEY already exists in ~/.openclaw/.env. Remove it first.");
      return { error: "already_exists" };
    }

    const pk      = generatePrivateKey();
    const account = privateKeyToAccount(pk);
    _mkdirSync(_envDir, { recursive: true });
    _appendFileSync(_envFile, `\nPRIVATE_KEY=${pk}\n`);

    console.log("✓ Wallet created\n");
    console.log(`  Address: ${account.address}\n`);
    console.log("Send to this address before trading:");
    console.log("  • ETH  — for gas");
    console.log(`  • Token  of the market— for buying shares`);
    console.log("\nPrivate key saved to ~/.openclaw/.env (never printed).");
    return { created: true, address: account.address };
  }

  // ── Status ──────────────────────────────────────────────────────────────────
  const pk = _getPrivateKey();
  if (!pk) {
    console.log("No wallet found.\n");
    console.log("  node setup.mjs --generate   create a new wallet");
    console.log("  or add PRIVATE_KEY=0x... to ~/.openclaw/.env");
    return { error: "no_wallet" };
  }

  const account = privateKeyToAccount(pk.startsWith("0x") ? pk : `0x${pk}`);
  console.log(`Wallet: ${account.address}\n`);

  const ethBal = await pub.getBalance({ address: account.address });
  console.log(`  ETH:  ${Number(formatEther(ethBal)).toFixed(6)} ${ethBal === 0n ? "⚠️  needs gas" : "✓"}`);

  let colInfo = null;
  try {
    const [token, , symbol, decimals] = await read("marketCollateralInfo", [0n]);
    const bal = await tokenBalance(token, account.address);
    console.log(`  ${symbol}: ${fromRaw(bal, Number(decimals))} ${bal === 0n ? "(no funds)" : "✓"}`);
    colInfo = { symbol, balance: bal };
  } catch {
    console.log(`  Collateral: (unavailable — check RPC or contract address)`);
  }

  return { address: account.address, ethBalance: ethBal, collateral: colInfo };
}

if (process.argv[1] === fileURLToPath(import.meta.url)) {
  main().catch(e => { console.error(e.message); process.exit(1); });
}

